import { test, mock } from 'node:test';
import assert from 'node:assert/strict';
import { debounce } from '../debounce.js';
test('waits and uses last args', () => {
  mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const d = debounce((...a) => calls.push(a), 100);
  d(1); mock.timers.tick(50); d(2); mock.timers.tick(99);
  assert.deepEqual(calls, []);
  mock.timers.tick(1);
  assert.deepEqual(calls, [[2]]);
  mock.timers.reset();
});
test('cancel and flush', () => {
  mock.timers.enable({ apis: ['setTimeout'] });
  const calls = [];
  const d = debounce((x) => calls.push(x), 100);
  d('a'); d.cancel(); mock.timers.tick(200);
  assert.deepEqual(calls, []);
  d('b'); d.flush();
  assert.deepEqual(calls, ['b']);
  mock.timers.tick(200);
  assert.deepEqual(calls, ['b']);
  d.flush();
  assert.deepEqual(calls, ['b']);
  mock.timers.reset();
});

